import { Mesh, PlaneGeometry, Group } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {any} config
 * @param {any} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Fallback config handling
  const imageUrl = config.imageUrl ?? (config.assets && config.assets.imageUrl);
  // Atlas region – defaults to full texture if not provided
  const atlas = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };
  const aspect = atlas.width / atlas.height;

  // Root container
  const root = new Group();

  // Geometry sized to the atlas aspect ratio
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  // Ensure the plane does not receive shadows (sprite‑like)
  mesh.castShadow = false;
  mesh.receiveShadow = false;
  root.add(mesh);

  // Billboard: orient toward the active camera each frame
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  // Load texture asynchronously and assign when ready
  let loadedTexture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // User data for event handlers (none for this node)
  root.userData.handlers = {};

  // Keep track of GSAP timelines for cleanup (none created here)
  const timelines = [];

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry
    geometry.dispose();
    // Dispose material
    material.dispose();
    // Dispose texture if we loaded one
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }
    // Kill any GSAP timelines
    timelines.forEach((tl) => tl.kill());
  };

  return root;
}
